function save(g=game){if(g?.practice278)return;if(!g?.environment156)return;try{localStorage.setItem(KEY,JSON.stringify(g.saveEnvironment156()));lastSave=g.environment156.elapsed;notice='Underlying environment saved; temporary previews excluded.';}catch{notice='Browser storage unavailable. Export JSON to save.';}}
